from pathlib import Path
import json,hashlib,html,shutil
w=Path(__file__).parent;report=Path('outputs/Stratus-1.6.9-visual-checks');(report/'screenshots').mkdir(parents=True,exist_ok=True)
rows=[]
for f in sorted((w/'screenshots').glob('*.png')):
 name=f.name
 if name=='v169-nonporous-sheen.png':status='REJECTED: initial distant fixture had not loaded. Repeated in confirmed and v2 captures.'
 elif name.startswith('s169-baseline'):status='Pre-existing 1.6.9-water-pole-test baseline; 854x480 and unfocused. Visual reference only.'
 elif '-game-vanilla' in name:status='Minecraft shaders disabled reference. Different water/sky/atmosphere are expected.'
 elif '-v2-' in name or '-release-' in name or '-active-' in name:status='Final runtime shader code; actual Main framebuffer. v2 uses refined film reflection.'
 elif '-confirmed-' in name:status='Accepted supporting v1 comparison with additional loading/readback wait. Water code matches final; film was subsequently refined.'
 else:status='Supporting preliminary v1 capture. Final film differs; do not use as final-code acceptance.'
 dest=report/'screenshots'/name;shutil.copy2(f,dest);rows.append({'file':name,'status':status,'sha256':hashlib.sha256(f.read_bytes()).hexdigest()})
(report/'captures.json').write_text(json.dumps(rows,indent=2)+'\n')
figures=''.join('<figure><a href="screenshots/'+html.escape(r['file'])+'"><img loading="lazy" src="screenshots/'+html.escape(r['file'])+'"></a><figcaption><b>'+html.escape(r['file'])+'</b><p>'+html.escape(r['status'])+'</p></figcaption></figure>' for r in rows)
(report/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stratus 1.6.9 — actual Main checks</title><style>body{font:16px/1.5 system-ui;background:#101821;color:#e8eff5;max-width:1500px;margin:auto;padding:30px}a{color:#9dd5ff}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,540px),1fr));gap:22px}figure{margin:0;padding:12px;background:#1d2b37;border-radius:10px}img{width:100%;display:block}figcaption{font-size:13px;overflow-wrap:anywhere}p{max-width:100ch}</style><h1>Stratus 1.6.9 — actual Minecraft checks</h1><p>22 October 2026. Main / Minecraft 1.21.11, Iris 1.10.8, Sodium 0.8.14, Apple M1. Normal Stratus Terrain Lab world. These are Minecraft framebuffer captures, not generated concepts or offline previews. Camera and pipeline guards ran before captures; one unloaded fixture is explicitly rejected.</p><p>Reviewed: vanilla terrain palette, porous/non-porous film without absorption, subtle native-water texture with off/strong comparison, river/underwater/waterline, Water and Materials menus. The original water-pole filter is preserved; its exact reported view is not independently certified. Early captures are 854×480; after the user focused the usual window, final v2 and focused captures are 1440×842. Cross-resolution images are not pixel-equivalence comparisons.</p><p>Performance is separate: see <a href="../../work/stratus-refine-169/performance-summary.json">focused benchmark summary</a> and <a href="../../work/Custom%20instructions/CHANGE-LOG.md">change log</a>. Initial unfocused samples are invalid; initial focused static samples hit Minecraft SHORT_AFK=30. Active samples retain saved settings while a temporary helper resets the inactivity timer, recording focus, limiter, camera, time and weather. Finite review does not certify every preset, motion, night, mod or weather case.</p><main>'''+figures+'</main></html>')
print(f'Created local visual report with {len(rows)} original captures and explicit acceptance labels.')
